import{_ as r,C as a,c as n,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Units of measure","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/products/units-of-measure.md","filePath":"master/supply-chain/inventories/products/units-of-measure.md","lastUpdated":1791902625000}'),l={name:"master/supply-chain/inventories/products/units-of-measure.md"};function u(d,e,c,g,h,m){const o=a("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="units-of-measure" tabindex="-1">Units of measure <a class="header-anchor" href="#units-of-measure" aria-label="Permalink to &quot;Units of measure&quot;">​</a></h1><p>A unit of measure tells Aureus how a quantity is counted. You may buy flour in kilograms, sell eggs by the dozen and count chairs as units. Units of measure are grouped in categories so Aureus only converts between units that fit together.</p><blockquote><p><strong>In simple words:</strong> A unit is how you count. A category keeps kilograms with weights and metres with lengths.</p></blockquote><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Go to <code>Inventory → Settings → Manage Products</code> and turn on <strong>Unit of Measure</strong>. The menu <code>Configurations → Units of Measure → UOM Categories</code> then appears, and products and moves show unit fields. See <a href="./../get-started/inventory-settings.html">Inventory settings</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Open <code>Inventory → Configurations → Units of Measure → UOM Categories</code>. The list shows <strong>Name</strong> and <strong>UOMs</strong>. Aureus ships six categories.</p>',7)),s(o,{src:"/images1/inventory/uom_categories_list.png",alt:"UOM categories list with Unit, Weight, Working Time, Length, Surface and Volume"}),e[1]||(e[1]=t('<table tabindex="0"><thead><tr><th>Category</th><th>Units</th></tr></thead><tbody><tr><td>Unit</td><td>Units, Dozens</td></tr><tr><td>Weight</td><td>kg, g, t, lb, oz</td></tr><tr><td>Working Time</td><td>Days, Hours</td></tr><tr><td>Length / Distance</td><td>m, mm, km, cm, in, ft, yd, mi</td></tr><tr><td>Surface</td><td>m², ft²</td></tr><tr><td>Volume</td><td>L, m³, fl oz (US), qt (US), gal (US), in³, ft³</td></tr></tbody></table><p>Rows have <strong>Edit</strong> and <strong>Delete</strong> actions.</p><h2 id="create-a-category" tabindex="-1">Create a category <a class="header-anchor" href="#create-a-category" aria-label="Permalink to &quot;Create a category&quot;">​</a></h2><ol><li>Go to <code>Inventory → Configurations → Units of Measure → UOM Categories</code>.</li><li>Click <strong>New UOM Category</strong>.</li></ol>',4)),s(o,{src:"/images1/inventory/uom_category_create.png",alt:"UOM category form named Packaging weight with units listed in the Units of Measure repeater"}),e[2]||(e[2]=t('<ul><li><strong><em>Name:</em></strong> Required. The category, for example <strong>Packaging weight</strong>.</li><li><strong>Units of Measure:</strong> Click <strong>Add Unit</strong> for each row. <ul><li><strong><em>Unit of Measure:</em></strong> Required. The unit name.</li><li><strong><em>Type:</em></strong> Required. The first row is the <strong>Reference</strong> unit. Later rows are bigger or smaller than it.</li><li><strong><em>Ratio:</em></strong> How many reference units fit in this one. Default 1. Locked for the Reference row.</li><li><strong><em>Rounding Precision:</em></strong> Required. The smallest step allowed. Default 0.01.</li></ul></li></ul><ol start="3"><li>Click <strong>Create</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Create the reference unit first. Set the other units against it. For example, kg is the reference and g has a smaller ratio.</p></div><h2 id="use-units-on-stock" tabindex="-1">Use units on stock <a class="header-anchor" href="#use-units-on-stock" aria-label="Permalink to &quot;Use units on stock&quot;">​</a></h2><p>Choose the unit on the product, and Aureus shows it on prices, order lines and stock moves. On a receipt, the <strong>Unit</strong> column shows the unit for each move. Quantities are converted to the product unit when stored.</p><p><strong>Example:</strong> Wheat Flour is held in <strong>kg</strong>. The sample warehouse holds 675 kg in <strong>WH/Stock</strong>.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>The reference unit is the base for the category. When you receive a different unit, Aureus converts it with the ratio. You cannot convert between categories, for example kilograms to metres.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This page covers the inventory view. The same records are managed in Sales. See <a href="./../../../sales/sales/configuration/uom-categories.html">UOM categories in Sales</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../get-started/inventory-settings.html">Inventory settings</a></li><li><a href="./configure-product.html">Configure a product</a></li><li><a href="./../../../sales/sales/configuration/uom-categories.html">UOM categories in Sales</a></li></ul>',11))])}const _=r(l,[["render",u]]);export{f as __pageData,_ as default};
